using Xunit;

public class ChemistLabTests
{
    [Fact]
    public void TC_001_EditUpdateChemistLabDetails()
    {
        // Arrange
        var chemistLabService = new ChemistLabService();
        var chemistLabId = "12345";
        var updatedChemistLab = new ChemistLab { Id = chemistLabId, Name = "Updated Chemist", Address = "Updated Address", ContactDetails = "Updated Contact" };

        // Act
        chemistLabService.EditChemistLab(chemistLabId, updatedChemistLab);

        // Assert
        var retrievedChemistLab = chemistLabService.GetChemistLab(chemistLabId);
        Assert.Equal(updatedChemistLab.Name, retrievedChemistLab.Name);
        Assert.Equal(updatedChemistLab.Address, retrievedChemistLab.Address);
        Assert.Equal(updatedChemistLab.ContactDetails, retrievedChemistLab.ContactDetails);
    }

    [Fact]
    public void TC_002_ChemistLabDoesNotExist()
    {
        // Arrange
        var chemistLabService = new ChemistLabService();
        var nonExistentChemistLabId = "99999";

        // Act & Assert
        Assert.Throws<Exception>(() => chemistLabService.GetChemistLab(nonExistentChemistLabId));
    }

    [Fact]
    public void TC_003_ChemistLabHasOpenPrescriptionRequests()
    {
        // Arrange
        var chemistLabService = new ChemistLabService();
        var chemistLabId = "12345";
        var prescription = new Prescription { ChemistLabId = chemistLabId };

        // Act & Assert
        Assert.Throws<Exception>(() => chemistLabService.DeleteChemistLab(chemistLabId));
    }
}

public class SymptomTests
{
    [Fact]
    public void TC_004_AddSymptomCode()
    {
        // Arrange
        var symptomService = new SymptomService();
        var symptomCode = "SYM001";
        var symptomDescription = "Symptom Description";

        // Act
        symptomService.AddSymptomCode(symptomCode, symptomDescription);

        // Assert
        var retrievedSymptom = symptomService.GetSymptomCode(symptomCode);
        Assert.Equal(symptomDescription, retrievedSymptom.Description);
    }

    [Fact]
    public void TC_005_EditUpdateSymptomCode()
    {
        // Arrange
        var symptomService = new SymptomService();
        var symptomCode = "SYM001";
        var updatedSymptomDescription = "Updated Symptom Description";

        // Act
        symptomService.EditSymptomCode(symptomCode, updatedSymptomDescription);

        // Assert
        var retrievedSymptom = symptomService.GetSymptomCode(symptomCode);
        Assert.Equal(updatedSymptomDescription, retrievedSymptom.Description);
    }

    [Fact]
    public void TC_006_SymptomDoesNotExist()
    {
        // Arrange
        var symptomService = new SymptomService();
        var nonExistentSymptomCode = "SYM999";

        // Act & Assert
        Assert.Throws<Exception>(() => symptomService.GetSymptomCode(nonExistentSymptomCode));
    }
}

public class PatientProfileTests
{
    [Fact]
    public void TC_007_UpdatePatientProfile()
    {
        // Arrange
        var patientProfileService = new PatientProfileService();
        var patientId = "P001";
        var updatedPatientProfile = new PatientProfile { Id = patientId, Name = "Updated Patient", Age = 30, Sex = "Male", Address = "Updated Address", ContactDetails = "Updated Contact" };

        // Act
        patientProfileService.UpdatePatientProfile(patientId, updatedPatientProfile);

        // Assert
        var retrievedPatientProfile = patientProfileService.GetPatientProfile(patientId);
        Assert.Equal(updatedPatientProfile.Name, retrievedPatientProfile.Name);
        Assert.Equal(updatedPatientProfile.Age, retrievedPatientProfile.Age);
        Assert.Equal(updatedPatientProfile.Sex, retrievedPatientProfile.Sex);
        Assert.Equal(updatedPatientProfile.Address, retrievedPatientProfile.Address);
        Assert.Equal(updatedPatientProfile.ContactDetails, retrievedPatientProfile.ContactDetails);
    }

    [Fact]
    public void TC_008_NewPatientRegistration()
    {
        // Arrange
        var patientProfileService = new PatientProfileService();
        var newPatientProfile = new PatientProfile { Name = "New Patient", Age = 25, Sex = "Female", Address = "New Address", ContactDetails = "New Contact" };

        // Act
        var patientId = patientProfileService.RegisterNewPatient(newPatientProfile);

        // Assert
        var retrievedPatientProfile = patientProfileService.GetPatientProfile(patientId);
        Assert.Equal(newPatientProfile.Name, retrievedPatientProfile.Name);
        Assert.Equal(newPatientProfile.Age, retrievedPatientProfile.Age);
        Assert.Equal(newPatientProfile.Sex, retrievedPatientProfile.Sex);
        Assert.Equal(newPatientProfile.Address, retrievedPatientProfile.Address);
        Assert.Equal(newPatientProfile.ContactDetails, retrievedPatientProfile.ContactDetails);
    }
}
